```js
import { LightningElement, api, wire } from 'lwc';
import { getRecord } from 'lightning/uiRecordApi';

const ACCOUNT_FIELDS = [
  'Account.Name',
  'Account.Industry',
  'Account.AnnualRevenue',
  'Account.Owner.Name'
];

export default class AccountHeader extends LightningElement {
  _recordId;
  data;
  error;

  @api
  get recordId() {
    return this._recordId;
  }

  @api
  set recordId(value) {
    if (value !== this._recordId) {
      this._recordId = value;
      this.data = undefined;
      this.error = undefined;
    } else {
      this._recordId = value;
    }
  }

  @wire(getRecord, { fields: ACCOUNT_FIELDS, recordId: 'recordId' })
  wiredAccount({ data, error }) {
    this.data = data;
    this.error = error;
  }

  get name() {
    return this.data?.fields?.Name?.value ?? '';
  }

  get industry() {
    const industry = this.data?.fields?.Industry?.value;
    return industry ? industry : undefined;
  }

  get revenue() {
    return this.data?.fields?.AnnualRevenue?.value ?? 0;
  }

  get ownerName() {
    return this.data?.fields?.Owner?.value?.Name?.value ?? '';
  }

  get errorMessage() {
    return this.error?.body?.message ?? '';
  }
}
```
