import { LightningElement, api } from 'lwc';

export default class OrderLinesPanel extends LightningElement {
    @api lines = [];

    hasError = false;

    get lineEditors() {
        return this.template.querySelectorAll('c-line-item-editor');
    }

    handleReset(event) {
        this.lineEditors.forEach(editor => editor.reset());
    }

    handleSubmit(event) {
        const editors = this.lineEditors;
        let allValid = true;

        editors.forEach(editor => {
            if (!editor.validate()) {
                allValid = false;
            }
        });

        if (allValid) {
            const values = editors.map(editor => editor.getValue());
            this.hasError = false;
            this.dispatchEvent(new CustomEvent('submit', {
                bubbles: true,
                composed: true,
                detail: { lines: values }
            }));
        } else {
            this.hasError = true;
        }
    }
}

